-- 2차 묶음 3 적용 확인(읽기 전용). applied_rows와 backed_up_rows가 120이면 정상.
WITH r AS (SELECT * FROM jsonb_to_recordset($payload$[{"id": 252, "word": "부동화", "beforeLength": 378, "after": "실물 증권을 예탁기관 한곳에 모아 두고 거래할 때 종이 증권을 옮기지 않는 방식이에요. 주인이 바뀌면 예탁기관 장부에서 계좌 사이 숫자만 옮겨 적어 권리를 넘겨요. 증권을 들고 다니다 잃어버리거나 도난당할 위험과 번거로운 사무 처리를 줄여 줘요."}, {"id": 253, "word": "부실채권(NPL)", "beforeLength": 355, "after": "빌려 간 사람의 형편이 나빠져 제때 돌려받기 어려워진 대출이에요. 보통 원금과 이자가 3개월 넘게 밀리면 고정 이하 등급으로 분류돼 여기에 들어가요. 이런 대출이 늘면 금융회사는 손실에 대비해 쌓아야 할 돈이 많아져 건전성이 나빠져요."}, {"id": 254, "word": "부채담보부증권(CDO)", "beforeLength": 665, "after": "회사채나 대출채권을 한데 묶은 뒤 위험 정도에 따라 여러 층으로 나눠 판 증권이에요. 손실이 나면 아래층인 후순위부터 떠안고, 위층인 선순위는 안전한 대신 이자가 낮아요. 구조가 복잡해 위험이 잘 안 보인다는 점이 2008년 금융위기 때 문제로 드러났어요."}, {"id": 255, "word": "부채비율", "beforeLength": 451, "after": "회사가 진 빚을 주주가 낸 자기자본으로 나눈 비율이에요. 예를 들어 자기자본이 100억 원인데 빚이 200억 원이면 이 비율은 200%가 돼요. 낮을수록 빚 부담이 적어 재무 구조가 튼튼하다고 봐요."}, {"id": 256, "word": "분리결제", "beforeLength": 320, "after": "증권을 넘겨주는 일과 돈을 치르는 일을 따로따로 처리하는 결제 방식이에요. 두 일 사이에 시간 차가 생겨 한쪽은 넘겨줬는데 상대가 이행하지 않을 수 있어요. 그래서 많은 나라는 증권과 대금을 동시에 주고받는 동시결제(DVP)를 주로 써요."}, {"id": 257, "word": "분산원장기술", "beforeLength": 697, "after": "거래 기록 장부를 한 기관의 서버가 아니라 여러 참여자가 나눠 갖고 함께 관리하는 기술이에요. 새 거래가 생기면 참여자들이 확인해 각자의 장부에 똑같이 기록해요. 중앙 관리 기관 없이도 기록을 믿을 수 있게 해 주며, 블록체인이 대표적인 예예요."}, {"id": 258, "word": "분수효과", "beforeLength": 443, "after": "저소득층과 중산층의 소득을 먼저 늘리면 경제 전체가 살아난다는 주장이에요. 이들이 늘어난 소득을 소비에 쓰면 기업의 생산과 투자가 늘고 결국 고소득층 소득도 늘어나요. 부유층과 대기업을 먼저 키우자는 낙수효과와 반대되는 생각이에요."}, {"id": 259, "word": "불완전경쟁시장", "beforeLength": 420, "after": "공급자가 적거나 상품이 서로 달라서 기업이 가격에 영향을 줄 수 있는 시장이에요. 공급자가 하나면 독점, 몇 곳뿐이면 과점, 조금씩 다른 상품을 파는 곳이 많으면 독점적 경쟁이라고 해요. 현실의 시장은 대부분 이 형태라 완전경쟁시장과 대비돼요."}, {"id": 260, "word": "불태화정책", "beforeLength": 538, "after": "외화가 많이 들어와 시중에 풀린 돈이 늘어날 때 중앙은행이 그만큼 다시 거둬들이는 정책이에요. 예를 들어 중앙은행이 채권을 팔면 그 대금만큼 시중의 돈이 흡수돼요. 외화 유입 때문에 금리나 물가가 원치 않게 움직이는 것을 막으려고 써요."}, {"id": 261, "word": "브레튼우즈체제", "beforeLength": 629, "after": "1944년 미국 브레튼우즈에서 연합국들이 합의해 만든 국제통화체제예요. 미국 달러를 일정 비율로 금과 바꿔 주고, 다른 나라 통화는 달러에 고정된 환율로 묶었어요. 달러가 세계의 기축통화가 된 출발점이었고 1970년대 초에 무너졌어요."}, {"id": 262, "word": "브렉시트(Brexit)", "beforeLength": 576, "after": "영국을 뜻하는 Britain과 탈퇴를 뜻하는 Exit를 합친 말로, 영국의 유럽연합 탈퇴를 가리켜요. 2016년 국민투표에서 탈퇴 찬성이 과반을 넘어 결정됐고 이후 협상을 거쳐 실제로 떠났어요. 무역과 이민 규칙이 바뀌면서 영국과 유럽 경제 모두에 큰 영향을 줬어요."}, {"id": 263, "word": "브릭스(BRICS)", "beforeLength": 666, "after": "브라질·러시아·인도·중국·남아프리카공화국의 영문 앞 글자를 딴 신흥 경제대국 모임이에요. 2001년 한 투자은행 경제학자가 성장 잠재력이 큰 네 나라를 묶어 부르며 처음 쓰였어요. 이후 남아공이 합류하고 정상회의를 열며 선진국 중심 질서에 맞서는 협의체가 됐어요."}, {"id": 264, "word": "브릿지론", "beforeLength": 373, "after": "큰 장기 자금이 마련되기 전까지 잠깐 다리를 놓듯 빌려 쓰는 단기 대출이에요. 예를 들어 부동산 개발 사업에서 본격적인 PF 대출을 받기 전에 땅을 사는 돈으로 써요. 기간이 짧고 위험이 커서 일반 대출보다 금리가 높은 편이에요."}, {"id": 265, "word": "비관측경제(NOE)", "beforeLength": 664, "after": "실제로 일어나지만 국내총생산을 계산할 때 쓰는 통계 자료에 잡히지 않는 경제활동이에요. 세금을 피하려고 숨긴 거래나 불법 생산, 집에서 쓰려고 만든 물건 등이 여기에 들어가요. 이 부분이 크면 공식 GDP가 실제 경제 규모보다 작게 나타날 수 있어요."}, {"id": 266, "word": "비교우위", "beforeLength": 497, "after": "다른 나라보다 더 적은 기회비용으로 어떤 물건을 만들 수 있는 능력이에요. 기회비용은 그 물건을 만드느라 포기한 다른 물건의 가치를 뜻해요. 각 나라가 이런 물건에 집중해 서로 바꾸면 모두 이득을 본다는 것이 리카도가 설명한 무역의 근거예요."}, {"id": 267, "word": "비용인상 인플레이션", "beforeLength": 383, "after": "임금이나 원자재처럼 물건을 만드는 데 드는 비용이 올라서 물가가 계속 오르는 현상이에요. 기업은 늘어난 생산비를 제품 가격에 얹어 팔기 때문에 최종 가격이 올라가요. 1970년대 석유 파동이 대표적인 예로, 생산까지 줄어 살림이 더 어려워지기 쉬워요."}, {"id": 268, "word": "비트코인", "beforeLength": 1032, "after": "중앙 관리자 없이 블록체인 기술로 운영되는 최초의 암호화폐예요. 거래는 은행 같은 중개자 없이 참여자끼리 직접 이뤄지고, 참여자들이 검증한 기록이 블록체인에 쌓여요. 2009년 사토시 나카모토라는 이름의 개발자가 처음 공개했으며 가격 변동이 매우 커요."}, {"id": 269, "word": "빅데이터", "beforeLength": 785, "after": "양이 아주 많고 형태가 다양한 데이터와 그 속에서 쓸모 있는 정보를 뽑아내는 기술을 함께 부르는 말이에요. 숫자뿐 아니라 글, 사진, 음성, 접속 기록처럼 정해진 틀이 없는 자료도 분석 대상이 돼요. 기업은 이를 활용해 고객 취향을 파악하거나 위험을 미리 찾아내요."}, {"id": 270, "word": "빅맥지수", "beforeLength": 582, "after": "세계 곳곳에서 파는 맥도날드 빅맥 가격을 비교해 각국 통화의 구매력을 가늠하는 지수예요. 같은 햄버거는 어디서나 값이 같아야 한다는 일물일가 법칙을 바탕으로 적정 환율을 계산해요. 영국 경제지 이코노미스트가 1986년부터 발표해 왔고 환율 수준을 쉽게 비교하는 데 쓰여요."}, {"id": 271, "word": "빈일자리율", "beforeLength": 97, "after": "기업이 사람을 구하고 있는 빈 일자리가 전체 일자리에서 차지하는 비율이에요. 빈 일자리 수를 현재 근로자 수와 빈 일자리 수를 더한 값으로 나눠 백분율로 계산해요. 이 비율이 높으면 일손이 부족하다는 뜻이라 노동시장 상황을 살피는 데 쓰여요."}, {"id": 272, "word": "사이드카", "beforeLength": 403, "after": "선물 가격이 크게 출렁일 때 주식시장의 프로그램 매매를 잠시 멈추는 안전장치예요. 코스피200 선물이 전날보다 5% 이상 오르거나 내린 상태가 1분 넘게 이어지면 5분 동안 효력이 정지돼요. 시장 전체를 멈추는 서킷브레이커와 달리 컴퓨터 자동 주문만 막는다는 점이 달라요."}, {"id": 273, "word": "사이버리스크", "beforeLength": 488, "after": "해킹이나 시스템 장애 같은 사이버 공간의 사고로 기업이 손실을 입을 위험이에요. 돈이나 고객 정보를 잃는 직접 피해뿐 아니라 신뢰 하락과 고객 이탈 같은 보이지 않는 피해도 생겨요. 업무가 디지털로 연결될수록 커지는 위험이라 보안 투자와 보험으로 대비해요."}, {"id": 274, "word": "사전적 정책방향 제시 (Forward Guidance)", "beforeLength": 661, "after": "중앙은행이 앞으로 기준금리를 어떻게 움직일지 미리 시장에 알려 주는 정책이에요. 예를 들어 상당 기간 낮은 금리를 유지하겠다고 밝히면 사람들의 금리 예상이 바뀌어 장기 금리도 내려가요. 금리를 더 내리기 어려웠던 글로벌 금융위기 이후 적극적으로 쓰이기 시작했어요."}, {"id": 275, "word": "사회보장제도", "beforeLength": 476, "after": "질병, 실업, 노령 같은 어려움이 닥쳐도 국민이 최소한의 인간다운 생활을 하도록 국가가 돕는 제도예요. 보험료를 내고 필요할 때 받는 사회보험, 세금으로 저소득층을 돕는 공공부조, 돌봄 같은 사회복지서비스로 나뉘어요. 국민연금과 건강보험이 대표적인 사회보험이에요."}, {"id": 277, "word": "산업연관표(I/O Tables)", "beforeLength": 533, "after": "한 해 동안 나라 안의 산업들이 서로 무엇을 얼마나 사고팔았는지 한 장에 정리한 통계표예요. 세로로 보면 각 산업이 무엇을 투입했는지, 가로로 보면 만든 물건이 어디로 팔렸는지 알 수 있어요. 어떤 수요가 늘 때 경제 전체에 미칠 효과를 계산하는 데 쓰여요."}, {"id": 278, "word": "삼불원칙", "beforeLength": 457, "after": "고정환율, 자유로운 자본 이동, 독자적인 통화정책 세 가지를 한꺼번에 가질 수 없다는 원칙이에요. 예를 들어 환율을 고정하고 자본 이동도 자유롭게 두면 금리를 마음대로 정하기 어려워져요. 그래서 각 나라는 셋 중 하나를 포기하는 선택을 하게 돼요."}, {"id": 279, "word": "상계관세", "beforeLength": 345, "after": "수출국 정부가 보조금을 줘서 싸게 들어온 수입품에 수입국이 추가로 매기는 관세예요. 보조금 덕분에 낮아진 가격만큼 관세를 더 얹어 가격 차이를 지워요. 국내 산업이 불공정한 가격 경쟁으로 피해를 보지 않도록 보호하려는 장치예요."}, {"id": 280, "word": "상장지수펀드(ETF)", "beforeLength": 632, "after": "주가지수 같은 특정 지수를 그대로 따라가도록 만든 펀드를 주식처럼 거래소에서 사고팔게 한 상품이에요. 예를 들어 코스피200을 따르는 상품을 사면 그 지수에 속한 여러 종목에 나눠 투자하는 효과가 나요. 일반 펀드보다 수수료가 낮고 장중에 바로 사고팔 수 있어 인기가 많아요."}, {"id": 281, "word": "상품공동기금(CFC)", "beforeLength": 382, "after": "커피, 코코아, 광물 같은 1차산품 가격을 안정시키고 개발도상국을 돕기 위해 1989년에 만든 국제 기금이에요. 1차산품의 생산과 교역 조건을 개선하는 연구와 사업에 자금을 지원해요. 1차산품 수출에 기대는 나라들이 가격 급변에 덜 흔들리도록 돕는 역할을 해요."}, {"id": 282, "word": "상품수지", "beforeLength": 368, "after": "우리나라가 외국에 상품을 판 금액과 사 온 금액의 차이로, 경상수지의 핵심 항목이에요. 수출이 수입보다 많으면 흑자, 적으면 적자로 표시해요. 관세선 통과를 기준으로 하는 무역수지와 달리 물건의 소유권이 바뀐 때를 기준으로 계산해 두 숫자가 다를 수 있어요."}, {"id": 283, "word": "상호관세", "beforeLength": 302, "after": "상대국이 우리 제품에 높은 관세를 매기면 우리도 그 나라 제품에 비슷한 수준의 관세를 매기는 것이에요. 받은 만큼 돌려준다는 방식이라 보복관세라고도 불려요. 무역 불균형을 바로잡는 수단이 될 수 있지만 서로 관세를 올리며 무역 분쟁이 커질 위험이 있어요."}, {"id": 284, "word": "생산세", "beforeLength": 431, "after": "부가가치세나 관세처럼 물건을 만들고 파는 과정에 붙는 세금으로, 예전에 간접세라 부르던 것이에요. 소득이나 재산에 매기는 세금과 달리 생산물 가격에 얹혀 결국 소비자가 부담하는 경우가 많아요. 국민계정에서 GDP와 국민소득을 계산할 때 따로 구분하는 항목이에요."}, {"id": 285, "word": "생산유발효과", "beforeLength": 544, "after": "소비나 수출 같은 최종수요가 늘어날 때 여러 산업의 생산이 줄줄이 늘어나는 효과예요. 예를 들어 자동차 수출이 늘면 엔진과 타이어가 더 필요하고, 다시 철강과 고무 생산도 늘어나요. 산업들이 서로 얽혀 있어 한 분야의 수요가 경제 전체로 퍼지는 크기를 보여 줘요."}, {"id": 286, "word": "생산자물가지수(PPI)", "beforeLength": 242, "after": "생산자가 국내 시장에 공급하는 상품과 서비스의 가격이 평균적으로 얼마나 변했는지 재는 물가지수예요. 소비자가 내는 가격이 아니라 생산자가 실제로 받는 가격을 기준으로 계산해요. 원재료와 중간재 가격 변화가 먼저 반영돼 앞으로의 소비자물가 흐름을 짐작하는 데도 쓰여요."}, {"id": 287, "word": "생산자제품재고지수", "beforeLength": 304, "after": "생산자가 팔지 않고 창고에 쌓아 둔 완제품 재고가 얼마나 늘고 줄었는지 보여 주는 지수예요. 원재료나 만들고 있는 중간 제품은 빼고 완성된 제품만 월말 기준으로 집계해요. 경기가 바뀐 뒤에 따라 움직이는 후행지표라 경기 흐름을 확인하는 데 쓰여요."}, {"id": 288, "word": "생산자제품출하지수", "beforeLength": 397, "after": "광공업 제품이 판매를 위해 공장 밖으로 얼마나 나갔는지 보여 주는 지수예요. 단순히 보관하려고 다른 창고로 옮기는 것은 빼고 실제로 팔려 나간 물량만 세어요. 생산자의 판매 활동을 바로 보여 줘 단기 경기 흐름을 판단하는 실물 지표로 쓰여요."}, {"id": 289, "word": "생산확산지수", "beforeLength": 523, "after": "전체 업종 가운데 생산이 늘어난 업종이 얼마나 되는지로 생산 증가가 얼마나 넓게 퍼졌는지 보는 지수예요. 전달보다 생산이 늘어난 업종은 1, 그대로인 업종은 0.5로 세어 전체 업종 수로 나눠 백분율로 계산해요. 50을 넘으면 생산이 늘어난 업종이 줄어든 업종보다 많다는 뜻이에요."}, {"id": 290, "word": "생성형 인공지능(AI)", "beforeLength": 652, "after": "많은 데이터를 학습한 뒤 글, 그림, 코드 같은 새로운 콘텐츠를 만들어 내는 인공지능이에요. 사람이 질문이나 지시를 입력하면 학습한 패턴을 바탕으로 그럴듯한 결과를 생성해요. 2020년대 들어 빠르게 발전하며 업무 방식과 산업 전반에 큰 변화를 가져오고 있어요."}, {"id": 291, "word": "생활물가지수", "beforeLength": 337, "after": "사람들이 자주 사고 지출 비중이 큰 생활필수품만 골라 만든 물가지수예요. 쌀처럼 장바구니에 자주 담아 가격 변화를 민감하게 느끼는 품목을 중심으로 계산해요. 더 많은 품목을 담는 소비자물가지수와 사람들이 느끼는 체감 물가의 차이를 설명하는 데 쓰여요."}, {"id": 292, "word": "서비스수지", "beforeLength": 376, "after": "운송, 여행, 금융처럼 형태가 없는 서비스를 외국과 거래해 벌어들인 돈과 내준 돈의 차이예요. 외국인 관광객이 국내에서 쓴 돈이나 우리 배가 받은 운임은 수입으로, 우리 국민이 해외여행에서 쓴 돈은 지급으로 잡혀요. 상품수지와 함께 경상수지를 이루는 주요 항목이에요."}, {"id": 293, "word": "서킷브레이커", "beforeLength": 584, "after": "주가가 짧은 시간에 급격히 움직일 때 주식시장의 거래를 잠시 멈추는 제도예요. 과열된 전기회로를 끊는 차단기에서 이름을 따왔고, 1987년 미국의 블랙 먼데이 폭락 이후 널리 도입됐어요. 투자자들이 잠시 숨을 고르게 해 공포에 따른 투매를 진정시키는 효과가 있어요."}, {"id": 294, "word": "서학개미", "beforeLength": 448, "after": "미국 등 해외 주식에 직접 투자하는 한국 개인투자자를 부르는 신조어예요. 서양을 뜻하는 서학과 개인투자자를 비유한 개미를 합친 말로, 국내 주식에 몰린 동학개미에 빗대어 생겼어요. 해외 투자가 늘면서 이들의 매매가 환율과 외화 흐름에도 영향을 줄 만큼 커졌어요."}, {"id": 295, "word": "선물거래", "beforeLength": 657, "after": "거래소에서 규격이 정해진 상품을 미래의 정해진 날에 지금 약속한 가격으로 사고팔기로 하는 거래예요. 계약은 오늘 하지만 물건과 돈은 만기일에 주고받아, 계약과 동시에 주고받는 현물거래와 달라요. 가격 변동 위험을 미리 막거나 가격 변화에 투자하려는 목적으로 많이 쓰여요."}, {"id": 296, "word": "선물환거래", "beforeLength": 605, "after": "지금 정한 환율로 미래의 특정한 날에 외화를 주고받기로 약속하는 거래예요. 예를 들어 6개월 뒤 달러를 받을 수출기업이 은행과 미리 환율을 정해 두면 그동안 환율이 떨어져도 손해를 보지 않아요. 주로 환율 변동 위험을 줄이려는 목적으로 이용돼요."}, {"id": 297, "word": "선물환포지션비율 규제", "beforeLength": 529, "after": "은행이 가진 선물 외화자산에서 선물 외화부채를 뺀 금액이 자기자본의 일정 비율을 넘지 않게 묶는 규제예요. 선물환 거래가 늘며 단기 외채가 급격히 쌓였던 경험을 계기로 2010년에 도입됐어요. 외화가 한꺼번에 빠져나갈 위험을 줄여 외환시장을 안정시키려는 장치예요."}, {"id": 298, "word": "선불카드(선불전자지급수단)", "beforeLength": 522, "after": "미리 돈을 충전해 두고 물건을 살 때마다 그 금액만큼 차감되는 카드예요. 여러 곳에서 쓸 수 있는 범용형과 특정 가게나 용도에만 쓰는 단일목적형으로 나뉘어요. 쓸 수 있는 돈이 충전한 금액으로 정해져 있어 나중에 갚는 신용카드와 달라요."}, {"id": 299, "word": "선행종합지수", "beforeLength": 288, "after": "실제 경기보다 먼저 움직이는 여러 지표를 묶어 앞으로의 경기 흐름을 예측하는 지수예요. 재고 흐름, 장단기 금리차, 주가지수, 소비자 기대 같은 지표를 가공해 하나로 합쳐요. 현재 경기를 보여 주는 동행종합지수, 뒤따라 움직이는 후행종합지수와 함께 경기 판단에 쓰여요."}, {"id": 300, "word": "세계경제포럼(다보스포럼)", "beforeLength": 721, "after": "세계의 기업인, 정치인, 학자들이 모여 세계 경제 문제를 토론하는 국제 민간 회의예요. 1971년 클라우스 슈바브가 만든 비영리 재단이 운영하며 매년 초 스위스 다보스에서 연차총회를 열어요. 세계 지도자들의 생각과 경제 흐름을 엿볼 수 있어 해마다 큰 관심을 받아요."}, {"id": 302, "word": "세계무역기구(WTO)", "beforeLength": 623, "after": "국제무역 규칙을 정하고 회원국 사이의 무역 분쟁을 해결하는 국제기구예요. 기존 GATT 체제를 보완하기 위한 협상을 거쳐 1995년에 출범했고 스위스 제네바에 본부가 있어요. 분쟁 조정 같은 강한 권한을 갖춰 자유무역 질서를 지키는 중심 역할을 해 왔어요."}, {"id": 303, "word": "세계은행(World Bank)", "beforeLength": 637, "after": "개발도상국의 경제 발전을 돕기 위해 장기 자금을 빌려주는 국제금융기구예요. 국제부흥개발은행(IBRD)과 가난한 나라에 낮은 이자로 지원하는 국제개발협회(IDA)를 합쳐 부르는 이름이에요. 2차 세계대전 뒤 복구 지원으로 시작했고 지금은 빈곤 감소 사업에 주로 힘써요."}, {"id": 304, "word": "소득5분위배율", "beforeLength": 172, "after": "소득 상위 20% 가구의 평균소득을 하위 20% 가구의 평균소득으로 나눈 값이에요. 전체 가구를 소득 순서대로 다섯 무리로 나눈 뒤 맨 위와 맨 아래 무리를 비교해요. 값이 클수록 부유한 가구와 가난한 가구의 소득 차이가 크다는 뜻이라 불평등 지표로 쓰여요."}, {"id": 305, "word": "소득교역조건지수", "beforeLength": 339, "after": "수출로 벌어들인 돈 전체로 수입할 수 있는 상품의 양이 기준 시점보다 얼마나 늘었는지 보여 주는 지수예요. 가격 조건을 보는 순상품교역조건지수에 수출 물량지수를 곱해 계산해요. 가격만 보는 지표와 달리 수출을 얼마나 많이 했는지까지 반영해 실제 구매력을 보여 줘요."}, {"id": 306, "word": "소득대체율", "beforeLength": 444, "after": "은퇴 뒤 받는 연금이 은퇴 전 소득의 몇 퍼센트인지 나타낸 비율이에요. 예를 들어 월 300만 원을 벌던 사람이 연금으로 매달 150만 원을 받으면 50%가 돼요. 노후 생활 수준이 얼마나 유지되는지 보여 줘 국민연금 제도를 평가하는 기준으로 쓰여요."}, {"id": 307, "word": "소매판매", "beforeLength": 315, "after": "대형마트, 백화점, 편의점, 온라인몰 등이 최종 소비자인 개인이나 가계에 물건을 파는 것이에요. 기업끼리 사고파는 도매와 달리 소비자가 직접 쓰려고 사는 거래만 해당해요. 사람들이 지갑을 얼마나 여는지 보여 줘 내수 경기를 판단하는 중요한 지표로 쓰여요."}, {"id": 308, "word": "소비의 비가역성", "beforeLength": 462, "after": "소득이 줄어도 한번 높아진 소비 수준을 그만큼 쉽게 낮추지 못하는 성질이에요. 사람들은 과거에 누리던 생활 수준을 기준으로 삼아 소득이 줄어든 폭보다 소비를 적게 줄여요. 이 때문에 경기가 나빠져도 소비가 급격히 줄지 않는 톱니효과가 나타나요."}, {"id": 309, "word": "소비자동향지수(CSI)", "beforeLength": 720, "after": "소비자에게 경기와 살림살이 형편, 앞으로의 지출 계획을 설문해 숫자로 만든 지수예요. 한국은행이 매달 전국 가구를 조사해 발표하며 100보다 크면 긍정적으로 보는 사람이 더 많다는 뜻이에요. 기업 심리를 보는 기업경기실사지수와 함께 대표적인 경제 심리 지표로 쓰여요."}, {"id": 310, "word": "소비자물가지수(CPI)", "beforeLength": 402, "after": "가계가 생활하며 사는 여러 상품과 서비스의 가격이 평균적으로 얼마나 변했는지 재는 물가지수예요. 기준 연도를 100으로 놓고 가계 지출에서 비중이 큰 품목들의 가격을 조사해 계산해요. 물가상승률을 말할 때 가장 널리 쓰이고 중앙은행 물가 목표의 기준이 돼요."}, {"id": 311, "word": "소비자심리지수", "beforeLength": 595, "after": "소비자 설문으로 만든 여러 심리 지수를 하나로 합쳐 소비자의 경기 인식을 종합적으로 보여 주는 지수예요. 생활형편, 수입과 지출 전망, 경기 판단 같은 주요 항목을 골라 합성하며 한국은행이 매달 발표해요. 100보다 높으면 경제를 낙관하는 소비자가 더 많다는 뜻이에요."}, {"id": 312, "word": "소액지급시스템", "beforeLength": 400, "after": "개인과 기업의 계좌이체, 카드 결제, 지로처럼 건수가 많은 소액 거래를 처리하는 지급시스템이에요. 거래를 건마다 결제하지 않고 모아 두었다가 은행끼리 주고받을 차액만 한 번에 정산해요. 한 은행이 차액을 못 내는 일에 대비해 담보나 한도 같은 안전장치를 둬요."}, {"id": 313, "word": "소프트랜딩", "beforeLength": 561, "after": "빠르게 달아오른 경기가 큰 충격 없이 천천히 식으며 안정되는 것을 말해요. 비행기가 부드럽게 착륙하는 모습에 빗댄 말로, 우리말로 연착륙이라고 해요. 반대로 경기가 갑자기 고꾸라지면 하드랜딩이라 하며, 물가를 잡으면서 침체는 피하려는 정책 목표로 자주 쓰여요."}, {"id": 314, "word": "소형모듈원자로(SMR)", "beforeLength": 499, "after": "기존 대형 원전보다 출력을 크게 줄이고 주요 부품을 공장에서 모듈로 만들어 현장에서 조립하는 원자력 발전소예요. 원자로와 증기발생기 같은 핵심 기기를 하나의 용기에 담아 구조가 단순해요. 건설 기간과 비용을 줄일 수 있어 차세대 전력원으로 주목받아요."}, {"id": 315, "word": "속물효과(스놉효과)", "beforeLength": 389, "after": "남들이 많이 사는 물건일수록 오히려 사지 않으려는 소비 현상이에요. 남과 다르게 보이고 싶어서 같은 옷을 입은 사람을 보면 그 옷을 더 이상 입지 않는 식이에요. 명품 소비에서 흔하며, 남들을 따라 사는 밴드왜건효과와 반대되는 개념이에요."}, {"id": 316, "word": "수요견인 인플레이션", "beforeLength": 361, "after": "경기가 과열돼 물건과 서비스를 사려는 수요가 공급보다 많아지면서 물가가 계속 오르는 현상이에요. 정부 지출 확대나 통화량 급증처럼 전체 수요를 늘리는 요인이 원인이 돼요. 생산비 상승이 원인인 비용인상 인플레이션과 달리 경기가 좋을 때 주로 나타나요."}, {"id": 317, "word": "수요탄력성", "beforeLength": 401, "after": "가격이 변할 때 사려는 양이 얼마나 민감하게 변하는지 나타낸 값이에요. 가격이 1% 오를 때 수요량이 1%보다 많이 줄면 탄력적, 적게 줄면 비탄력적이라고 해요. 쌀 같은 생필품은 비탄력적이고 사치품은 탄력적인 편이라 기업의 가격 전략에 쓰여요."}, {"id": 318, "word": "수익률곡선", "beforeLength": 392, "after": "만기가 짧은 채권부터 긴 채권까지 수익률을 이어 그린 곡선이에요. 가로축은 만기, 세로축은 수익률로 그리며 보통은 만기가 길수록 수익률이 높아 오른쪽 위로 향해요. 장단기 금리가 뒤집혀 곡선이 거꾸로 기울면 경기침체 신호로 해석되기도 해요."}, {"id": 319, "word": "수입유발계수", "beforeLength": 199, "after": "소비나 수출 같은 최종수요가 한 단위 늘어날 때 수입이 얼마나 함께 늘어나는지 나타낸 계수예요. 완제품을 만들려면 원자재와 부품이 필요하니 직접 수입뿐 아니라 여러 산업을 거친 간접 수입까지 모두 더해요. 값이 클수록 늘어난 수요의 효과가 해외로 많이 새어 나간다는 뜻이에요."}, {"id": 320, "word": "수출경합도지수", "beforeLength": 338, "after": "두 나라가 같은 시장에 수출하는 품목 구성이 얼마나 비슷한지 재는 지표예요. 품목마다 두 나라 수출에서 차지하는 비중을 비교해 작은 쪽을 골라 모두 더한 뒤 100을 곱해 계산해요. 100에 가까울수록 수출 구조가 닮아 그 시장에서 서로 치열하게 경쟁한다는 뜻이에요."}, {"id": 321, "word": "수출보험", "beforeLength": 317, "after": "수입업자가 부도나거나 수입국에 전쟁 같은 사정이 생겨 수출 대금을 받지 못할 때 손실을 보상해 주는 보험이에요. 민간 보험사가 감당하기 어려운 위험이라 우리나라는 정부 출연 기금을 바탕으로 한국무역보험공사가 운영해요. 수출기업이 낯선 시장에도 안심하고 진출하도록 돕는 수단이에요."}, {"id": 322, "word": "수출입물가지수", "beforeLength": 304, "after": "우리나라가 수출하는 상품과 수입하는 상품의 가격이 얼마나 변했는지 재는 물가지수예요. 수입물가가 오르면 원자재 비용이 늘어 시차를 두고 국내 물가도 오르기 쉬워요. 기업의 수출 채산성과 수입 원가 부담을 살피고 교역조건을 계산하는 데 쓰여요."}, {"id": 323, "word": "수출입물량지수", "beforeLength": 228, "after": "가격 변동 효과를 빼고 수출입 물량 자체가 얼마나 늘거나 줄었는지 보여 주는 지수예요. 수출입 금액지수를 수출입 물가지수로 나눠 계산해요. 유가처럼 가격이 크게 움직여 금액이 출렁일 때 실제 거래량의 변화를 파악하는 데 쓰여요."}, {"id": 324, "word": "수확체감의 법칙", "beforeLength": 295, "after": "다른 생산요소는 그대로 두고 한 가지만 계속 늘리면 어느 순간부터 추가로 얻는 생산량이 줄어드는 현상이에요. 예를 들어 같은 크기의 밭에 일꾼을 계속 더 넣으면 처음엔 수확이 크게 늘다가 점점 늘어나는 폭이 작아져요. 투입만 무작정 늘리기보다 요소를 고르게 갖추는 것이 중요한 이유예요."}, {"id": 325, "word": "순상품교역조건지수", "beforeLength": 515, "after": "수출품 1단위를 팔아 수입할 수 있는 상품의 양이 기준 시점보다 얼마나 변했는지 보여 주는 지수예요. 수출물가지수를 수입물가지수로 나눠 계산해요. 값이 오르면 같은 양을 수출해 더 많이 수입할 수 있어 가격 면에서 교역 여건이 좋아졌다는 뜻이에요."}, {"id": 327, "word": "순이자마진(NIM)", "beforeLength": 138, "after": "은행이 굴린 자산에서 번 이자수익에서 조달에 든 이자비용을 뺀 뒤 운용 자산 규모로 나눈 비율이에요. 대출로 받는 이자와 예금에 주는 이자의 차이가 클수록 이 값이 커져요. 은행이 본업인 돈 장사로 얼마나 수익을 내는지 보여 주는 핵심 지표예요."}, {"id": 328, "word": "순이체한도제", "beforeLength": 529, "after": "은행끼리 주고받을 돈을 모았다가 차액만 정산할 때 각 은행이 낼 순이체액에 상한을 정해 두는 제도예요. 보낸 돈에서 받은 돈을 뺀 금액이 한도에 이르면 더 이상 이체를 보낼 수 없어요. 한 은행이 결제를 못 하는 일이 생겨도 피해 규모를 제한하려는 장치예요."}, {"id": 329, "word": "숨은 그림(은화)", "beforeLength": 289, "after": "지폐를 빛에 비췄을 때 여백에 나타나는 위조 방지용 문양이에요. 종이를 만들 때 부분마다 두께를 다르게 해 빛이 통과하는 정도가 달라지면서 명암으로 그림이 드러나요. 우리나라 지폐에는 앞면 인물 초상이 숨어 있어 진짜 돈인지 쉽게 확인할 수 있어요."}, {"id": 330, "word": "스무딩오퍼레이션", "beforeLength": 383, "after": "환율이 너무 빠르게 움직일 때 외환당국이 시장에 들어가 변동 속도를 늦추는 미세조정이에요. 환율이 급히 떨어지면 달러를 사들이고, 급히 오르면 달러를 팔아 흐름을 완만하게 만들어요. 환율 수준 자체를 정하려는 것이 아니라 급격한 쏠림만 막는다는 점이 특징이에요."}, {"id": 331, "word": "스왑", "beforeLength": 712, "after": "두 당사자가 미리 정한 조건에 따라 일정 기간 이자나 원금 같은 돈의 흐름을 서로 바꾸는 계약이에요. 예를 들어 변동금리를 내는 회사와 고정금리를 내는 회사가 이자 지급 방식을 맞바꿀 수 있어요. 금리나 환율이 변하는 위험을 줄이는 데 널리 쓰이는 파생상품이에요."}, {"id": 332, "word": "스왑레이트", "beforeLength": 531, "after": "미래 환율인 선물환율과 지금 환율인 현물환율의 차이를 현물환율로 나누고 1년 기준으로 환산한 비율이에요. 이론적으로는 두 나라 통화의 금리 차이와 같아지도록 움직여요. 국내 금융회사들이 달러를 구하기 어려워지면 이 값이 떨어져 외화 자금 사정을 보여 주는 지표로도 쓰여요."}, {"id": 333, "word": "스왑베이시스", "beforeLength": 358, "after": "통화스왑 금리와 금리스왑 금리의 차이를 말해요. 통화스왑 금리는 원화를 맡기고 달러를 빌릴 때의 비용이고, 금리스왑 금리는 원화를 고정금리로 조달하는 비용을 뜻해요. 이 차이가 마이너스로 크게 벌어질수록 달러를 구하기 어렵다는 신호로 해석돼요."}, {"id": 334, "word": "스태그플레이션", "beforeLength": 398, "after": "경기가 침체해 실업이 늘어나는데도 물가는 계속 오르는 현상이에요. 경기침체를 뜻하는 스태그네이션과 인플레이션을 합친 말로, 1970년대 두 차례 석유 파동 때 크게 나타났어요. 물가를 잡으려 하면 경기가 더 나빠지고 경기를 살리려 하면 물가가 더 올라 대응이 어려워요."}, {"id": 335, "word": "스탠더드&푸어스(S&P)", "beforeLength": 533, "after": "무디스, 피치와 함께 세계 3대 국제신용평가기관으로 꼽히는 미국 회사예요. 나라와 기업이 발행한 채권의 원리금 상환 능력을 평가해 최고 등급인 AAA부터 여러 단계의 등급을 매겨요. 이 등급에 따라 채권 금리와 자금 조달 비용이 달라져 시장에 큰 영향을 줘요."}, {"id": 336, "word": "스테이블코인", "beforeLength": 492, "after": "미국 달러 같은 기준 자산에 가치를 연동해 가격이 크게 흔들리지 않도록 설계한 가상자산이에요. 발행한 만큼 법정화폐를 담보로 쌓아 두거나, 다른 암호자산을 담보로 잡거나, 알고리즘으로 공급량을 조절해요. 가격 변동이 큰 비트코인과 달리 결제나 송금 수단으로 쓰기 쉬워요."}, {"id": 337, "word": "스톡옵션", "beforeLength": 502, "after": "회사가 임직원에게 정해진 기간이 지난 뒤 자사 주식을 미리 정한 가격에 살 수 있게 주는 권리예요. 회사 가치가 올라 주가가 약속한 가격보다 높아지면 싸게 사서 그 차익을 얻을 수 있어요. 직원이 회사 성장에 힘쓰도록 하는 보상 수단으로 스타트업에서 특히 많이 쓰여요."}, {"id": 338, "word": "스트레스 DSR", "beforeLength": 638, "after": "앞으로 금리가 오를 수 있다고 가정해 대출 한도를 계산할 때 일정 수준의 가산금리를 더 얹는 제도예요. 가산금리는 한도 계산에만 쓰이고 실제로 내는 대출 이자에는 붙지 않아요. 금리가 올라도 감당할 수 있는 만큼만 빌리게 해 가계부채가 과하게 늘어나는 것을 막아요."}, {"id": 339, "word": "스트레스 테스트(위기상황분석)", "beforeLength": 402, "after": "극단적이지만 실제로 일어날 수 있는 위기 상황을 가정해 금융회사가 버틸 수 있는지 점검하는 방법이에요. 예를 들어 집값과 주가가 크게 떨어지는 상황에서 손실과 자본비율이 어떻게 변하는지 계산해요. 위기가 오기 전에 약한 곳을 찾아 미리 자본을 늘리거나 위험을 줄이도록 하는 데 쓰여요."}, {"id": 340, "word": "시뇨리지", "beforeLength": 428, "after": "중앙은행이나 국가가 화폐를 발행해서 얻는 이익이에요. 옛날에는 금화를 만드는 비용보다 높은 액면가로 유통해 그 차이가 이익이 됐어요. 요즘은 화폐를 발행해 사들인 자산에서 나오는 운용수익에서 화폐 제조비 등을 뺀 것을 가리켜요."}, {"id": 341, "word": "시스템 리스크", "beforeLength": 392, "after": "금융시스템의 일부가 무너지면서 돈을 빌려주고 빌리는 금융 기능 전체가 마비될 위험이에요. 금융회사들이 서로 얽혀 한 곳의 부실이 번지거나, 호황기에 다 같이 대출을 늘렸다가 함께 무너지며 생겨요. 실물경제까지 크게 흔들 수 있어 개별 회사의 위험보다 엄격히 관리해요."}, {"id": 342, "word": "시스템적으로 중요한 금융기관", "beforeLength": 720, "after": "규모가 크고 다른 금융회사와 연결이 많아 무너지면 금융시스템 전체가 흔들리는 대형 금융회사예요. 이런 회사가 부실해지면 정부가 세금으로 살려야 하는 대마불사 문제가 생기기 쉬워요. 그래서 일반 금융회사보다 자본을 더 쌓게 하는 등 더 엄격한 규제를 적용해요."}, {"id": 343, "word": "시장리스크", "beforeLength": 277, "after": "금리, 주가, 환율이 변하면서 은행이 사고팔려고 보유한 금융상품 가격이 떨어져 손실이 날 위험이에요. 예를 들어 금리가 오르면 은행이 들고 있던 채권 가격이 내려가 손실이 생겨요. 국제 은행 규제인 바젤 기준은 이 위험에 맞춰 일정한 자기자본을 갖추도록 요구해요."}, {"id": 344, "word": "시장평균환율(MAR)", "beforeLength": 521, "after": "외국환중개회사를 통해 은행끼리 거래된 환율을 거래량으로 가중평균해 만든 환율이에요. 거래가 많이 이뤄진 환율일수록 더 큰 비중으로 반영돼요. 이렇게 구한 값은 다음 영업일의 기준환율이 돼 외환 거래와 원화 환산의 기준으로 쓰여요."}, {"id": 345, "word": "시장평균환율제도", "beforeLength": 493, "after": "전날 시장평균환율을 기준으로 하루 동안 환율이 정해진 범위 안에서만 움직이도록 한 제도예요. 우리나라가 1990년에 도입해 시장의 수요와 공급으로 환율이 정해지게 하되 급격한 변동은 막았어요. 1997년 외환위기 이후 지금의 자유변동환율제도로 바뀌었어요."}, {"id": 346, "word": "시카고 연준 금융상황지수", "beforeLength": 343, "after": "미국 시카고 연방준비은행이 미국 금융시장의 돈줄이 조이는 쪽인지 풀리는 쪽인지 보여 주려고 만든 지수예요. 신용 스프레드, 부채 수준, 변동성 같은 여러 금융 변수를 모아 하나의 숫자로 계산해요. 0보다 크면 평소보다 긴축적이고 0보다 작으면 완화적이라는 뜻이에요."}, {"id": 347, "word": "시카고상업거래소(CME)", "beforeLength": 499, "after": "농산물과 금융상품 선물을 주로 거래하는 세계 최대 규모의 파생상품 거래소예요. 1898년 버터와 계란을 거래하던 상인 모임에서 출발해 이후 통화와 금리 선물까지 넓혔어요. 이곳의 금리 선물 가격은 미국 기준금리 전망을 읽는 데 자주 쓰여요."}, {"id": 348, "word": "신용경색", "beforeLength": 589, "after": "금융회사가 돈을 잘 빌려주지 않아 기업과 가계가 필요한 자금을 구하지 못하는 현상이에요. 일부 은행이 부실해지면 다른 금융회사도 떼일까 겁나 대출을 줄이면서 돈줄이 막혀요. 멀쩡한 기업도 자금이 돌지 않아 쓰러질 수 있어 경기침체로 이어지기 쉬워요."}, {"id": 349, "word": "신용레버리지", "beforeLength": 625, "after": "수익을 키우려고 빚을 얼마나 끌어다 쓰고 있는지를 나타내는 정도예요. 지렛대처럼 남의 돈을 보태 투자하면 이익이 날 때 내 돈 대비 수익률이 크게 높아져요. 반대로 손실이 나면 피해도 그만큼 커지기 때문에 지나친 빚 투자는 위험해요."}, {"id": 350, "word": "신용스프레드", "beforeLength": 588, "after": "회사채 금리와 같은 만기 국고채 금리의 차이예요. 예를 들어 회사채 금리가 4%이고 같은 만기 국고채가 3%라면 차이는 1%포인트예요. 회사가 돈을 못 갚을 위험이 클수록 이 차이가 벌어져 시장의 불안 정도를 보여 줘요."}, {"id": 352, "word": "신용위험(신용리스크)", "beforeLength": 346, "after": "돈을 빌려 간 쪽이 갚지 못하거나 신용이 나빠져 빌려준 쪽이 손실을 볼 가능성이에요. 금융회사는 부도 확률, 부도 때 실제로 잃는 비율, 떼일 수 있는 금액을 따져 위험 크기를 계산해요. 은행이 가장 크게 안고 있는 위험이라 이에 맞춰 자기자본을 쌓도록 규제해요."}, {"id": 353, "word": "신용창조", "beforeLength": 735, "after": "은행이 예금을 받아 대출하고 그 돈이 다시 예금으로 들어오는 과정이 반복되며 통화가 불어나는 현상이에요. 지급준비율이 10%라면 받은 예금의 90%를 빌려주고, 그 돈이 다른 은행에 예금돼 또 대출로 이어져요. 그래서 처음 돈의 몇 배에 이르는 예금통화가 생겨요."}, {"id": 354, "word": "신용파생상품", "beforeLength": 662, "after": "채권이나 대출에서 돈을 떼일 위험인 신용위험만 따로 떼어 내 다른 사람에게 넘기는 금융상품이에요. 위험을 넘기는 쪽은 수수료를 내고, 받는 쪽은 부도가 나면 손실을 대신 메워 줘요. 대표적인 상품으로 신용부도스왑(CDS)이 있으며 대출을 그대로 둔 채 위험만 줄일 수 있어요."}, {"id": 355, "word": "신용평가제도", "beforeLength": 673, "after": "기업이나 개인이 빚을 제때 갚을 능력이 얼마나 되는지 평가해 등급으로 매기는 제도예요. 기업이 채권을 낼 때는 신용평가회사가 등급을 매기고, 개인이 대출받을 때는 금융회사가 신용도를 따져요. 등급이 좋을수록 낮은 금리로 돈을 빌릴 수 있어 자금 조달 비용을 좌우해요."}, {"id": 356, "word": "신용환산율", "beforeLength": 386, "after": "지급보증처럼 아직 장부에 대출로 잡히지 않은 거래가 실제 대출로 바뀔 가능성을 반영하는 비율이에요. 은행 자본 규제에서 이런 장부 밖 거래의 약정 금액에 이 비율을 곱해 위험 노출 금액을 계산해요. 당장 돈이 나가지 않는 약속도 손실이 될 수 있어 자본을 미리 쌓게 하려는 장치예요."}, {"id": 357, "word": "신주인수권부사채(BW)", "beforeLength": 587, "after": "새 주식을 미리 정한 가격에 살 수 있는 권리인 워런트가 붙은 회사채예요. 주가가 약속한 가격보다 오르면 권리를 써서 싸게 사 차익을 얻고, 아니면 권리를 포기하고 채권 이자만 받아요. 이런 권리가 붙어 있어 회사는 일반 회사채보다 낮은 금리로 돈을 빌릴 수 있어요."}, {"id": 358, "word": "신흥시장국채권지수(EMBI+)", "beforeLength": 421, "after": "신흥국 정부가 국제시장에서 발행한 달러 표시 국채의 수익률을 바탕으로 만든 대표 채권지수예요. 글로벌 투자은행 JP모건이 계산하며 신흥국 채권의 가산금리를 거래 규모에 따라 가중평균해요. 신흥국 채권 펀드의 기준으로 쓰이고 신흥국 위험이 얼마나 큰지 보여 줘요."}, {"id": 359, "word": "실망실업자", "beforeLength": 309, "after": "일할 의사와 능력이 있지만 마땅한 일자리가 없을 것 같아 최근 4주 동안 구직을 하지 않은 사람이에요. 지난 1년 안에 일자리를 찾아본 적이 있어야 하며, 통계에서는 실업자가 아닌 비경제활동인구로 분류돼요. 이들이 늘면 실업률은 낮아 보여도 실제 고용 사정은 나쁠 수 있어요."}, {"id": 360, "word": "실물화폐", "beforeLength": 433, "after": "조개, 곡물, 가축처럼 그 자체로 쓸모와 가치가 있어 돈으로 쓰인 물건이에요. 사람들은 이런 물건을 주고받으며 교환했고, 점차 들고 다니기 쉽고 변하지 않는 금과 은을 주로 썼어요. 경제 규모가 커지면서 운반과 보관이 불편해 종이돈 같은 화폐로 바뀌었어요."}, {"id": 361, "word": "실시간총액결제", "beforeLength": 416, "after": "은행끼리 주고받을 돈을 서로 상계하지 않고 지급 지시가 들어올 때마다 건별로 전액을 즉시 처리하는 결제 방식이에요. 한꺼번에 모아 차액만 정산하는 차액결제와 달리 바로 결제가 끝나요. 상대 은행이 못 갚을 위험이 생기지 않아 큰돈이 오가는 거액 결제에 주로 쓰여요."}, {"id": 362, "word": "실업률갭", "beforeLength": 540, "after": "실제 실업률과 경제가 정상일 때의 실업률인 자연실업률의 차이예요. 실제 실업률이 더 높으면 노동시장에 여유가 있어 임금과 물가가 오를 압력이 약해요. 반대로 더 낮으면 일손 확보 경쟁으로 임금이 올라 물가를 끌어올릴 수 있어요."}, {"id": 363, "word": "실질구매력", "beforeLength": 376, "after": "물가 변화를 감안했을 때 같은 돈으로 실제 살 수 있는 물건과 서비스의 양이에요. 월급이 그대로여도 물가가 오르면 살 수 있는 양이 줄어 구매력이 낮아져요. 그래서 소득이 늘었는지 볼 때는 금액보다 물가를 뺀 실제 가치를 따져야 해요."}, {"id": 364, "word": "실질임금", "beforeLength": 185, "after": "받는 월급 액수인 명목임금을 물가지수로 나눠 실제로 살 수 있는 양을 기준으로 본 임금이에요. 예를 들어 월급이 3% 올랐는데 물가가 5% 올랐다면 실질임금은 오히려 줄어요. 근로자의 생활 수준이 실제로 나아졌는지 판단할 때 쓰여요."}, {"id": 365, "word": "실효환율", "beforeLength": 613, "after": "여러 교역상대국 통화에 대한 우리 통화의 가치를 각 나라와의 무역 비중에 따라 평균 낸 환율이에요. 달러 대비 환율만 보면 놓치는 다른 나라 통화와의 관계까지 함께 반영해요. 여기에 물가 차이까지 고려한 실질실효환율은 수출 가격경쟁력을 판단하는 지표로 쓰여요."}, {"id": 366, "word": "쌍순환 전략", "beforeLength": 453, "after": "국내 소비·투자와 수출이라는 두 축을 함께 키우겠다는 중국의 경제 전략이에요. 미국과의 무역 갈등이 심해진 2020년 무렵 제시됐으며, 국내 순환을 중심에 두고 해외 순환이 이를 뒷받침하게 한다는 구상이에요. 외부 충격에 흔들리지 않도록 내수와 기술 자립을 강화하려는 목적이 커요."}, {"id": 367, "word": "아세안+3 거시경제조사기구(AMRO)", "beforeLength": 801, "after": "아세안 회원국과 한국·중국·일본이 역내 경제를 함께 감시하려고 만든 국제기구예요. 위기 때 서로 외화를 빌려주는 치앙마이 이니셔티브가 잘 작동하도록 회원국 경제를 분석하고 점검해요. 2011년 싱가포르에 세워졌으며 회원국의 경제 위험을 미리 찾아내 알리는 역할을 해요."}, {"id": 368, "word": "아시아개발은행(ADB)", "beforeLength": 659, "after": "아시아·태평양 지역 개발도상국의 경제 발전을 돕기 위해 1966년에 세운 국제금융기구예요. 회원국이 낸 출자금과 빌린 돈으로 개발 사업에 자금을 빌려주고 사업 계획 수립 같은 기술도 지원해요. 본부는 필리핀 마닐라에 있으며 일본과 미국이 가장 큰 출자국이에요."}, {"id": 369, "word": "아시아인프라은행(AIIB)", "beforeLength": 824, "after": "아시아 개발도상국의 도로, 항만, 전력 같은 인프라 건설 자금을 지원하려고 중국 주도로 만든 국제금융기구예요. 2016년 베이징에서 출범했으며 우리나라도 창립 회원국으로 참여했어요. 선진국 중심으로 운영되던 기존 개발은행에 신흥국 목소리가 잘 반영되지 않는다는 비판을 배경으로 생겼어요."}, {"id": 370, "word": "아시아태평양경제협력체(APEC)", "beforeLength": 617, "after": "아시아와 태평양 연안 국가들이 무역과 투자를 자유롭게 하고 경제협력을 넓히려고 만든 협의체예요. 1989년 호주 캔버라에서 열린 첫 각료회의로 출범했으며 한국도 창립 회원이에요. 매년 회원국을 돌며 정상회의를 열어 지역 경제 현안을 논의해요."}, {"id": 371, "word": "애그플레이션", "beforeLength": 699, "after": "농산물 가격이 급등하면서 전체 물가까지 끌어올리는 현상이에요. 농업을 뜻하는 Agriculture와 인플레이션을 합친 말로, 이상기후나 바이오연료 수요 증가가 주요 원인이 돼요. 곡물은 사료와 가공식품의 원료라 가격이 오르면 고기와 빵값까지 줄줄이 올라요."}, {"id": 372, "word": "양도성예금증서(CD)", "beforeLength": 750, "after": "은행 정기예금증서에 남에게 사고팔 수 있는 권리를 붙인 단기 금융상품이에요. 만기 전에 해지할 수는 없지만 시장에서 다른 사람에게 팔아 현금으로 바꿀 수 있어요. 이 증서의 금리는 오랫동안 변동금리 대출의 기준금리로 쓰여 왔어요."}, {"id": 373, "word": "양적완화정책", "beforeLength": 1009, "after": "기준금리가 거의 0이라 더 내릴 수 없을 때 중앙은행이 국채 등을 대량으로 사들여 시중에 돈을 푸는 정책이에요. 채권을 사면 그 대금이 시장에 풀리고 장기 금리가 내려가 투자와 소비를 돕게 돼요. 2001년 일본이 처음 시행했고 글로벌 금융위기 때 미국 등으로 퍼졌어요."}, {"id": 374, "word": "어음관리계좌(CMA)", "beforeLength": 443, "after": "증권사나 종합금융회사에 맡긴 돈을 어음이나 채권 같은 단기 상품에 굴려 수익을 돌려주는 계좌예요. 하루만 맡겨도 이자가 붙고 은행 통장처럼 자유롭게 넣고 뺄 수 있어요. 잠깐 쉬는 돈을 보관하면서 보통예금보다 조금 더 높은 수익을 노릴 때 많이 쓰여요."}, {"id": 375, "word": "어음교환", "beforeLength": 535, "after": "은행들이 각자 받은 수표와 어음 가운데 다른 은행이 지급해야 할 것을 서로 맞바꾸고 차액을 정산하는 일이에요. 각 은행이 일일이 상대 은행을 찾아가 돈을 받지 않고 한곳에서 한꺼번에 처리해요. 은행의 업무 부담과 비용을 줄이고 돈을 받기까지 걸리는 시간을 단축해 줘요."}]$payload$::jsonb) AS r(id integer, word text, "beforeLength" integer, after text))
SELECT count(*) FILTER (WHERE w.detailed_meaning = r.after) AS applied_rows,
       count(b.id) AS backed_up_rows,
       120 AS expected
FROM r JOIN public.words w ON w.id = r.id
LEFT JOIN public.words_detailed_meaning_backup_v1 b ON b.id = r.id;
